INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_002_001", 1000, 1, 2, "訓練はまだ\nここからですわ", 2, 3000, "vo_minigame_1013_icon_2_002_001", "調子が上がって\nきたなっ", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_003_001", 5000, 2, 2, "クスクス、悪くない\n流れですわね", 2, 3000, "vo_minigame_1013_icon_2_003_001", "ほらほら、\nまだいけるだろ？", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_004_001", 10000, 3, 3, "すばらしい\n記録ですわ", 2, 3000, "vo_minigame_1013_icon_2_004_001", "へへっ、おまえら\nやるじゃねえか！", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_005_001", 10000, 4, 3, "乗りに乗って\nいますわね", 3, 3000, "vo_minigame_1013_icon_2_005_001", "あたしたちはまだ\n止まらねえぜ！", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_005_002", 10000, 5, 3, "まだまだ行きます\nついてきなさい", 3, 3000, "vo_minigame_1013_icon_2_005_002", "見てろよ！\nマコト班の快進撃だ！", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_005_003", 10000, 6, 3, "エリコ班の\n本領発揮ですわ！", 3, 3000, "vo_minigame_1013_icon_2_005_003", "うおぉぉっ！\n絶好調だぜ！", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_006_001", 0, 7, 3, "ここからは\n前人未到の領域です！", 4, 3000, "vo_minigame_1013_icon_2_006_001", "どこまで行けるか\n楽しみだなっ！", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_007_001", 1, 8, 4, "厄介でしたわ…", 5, 1000, "vo_minigame_1013_icon_2_007_001", "まだ諦めんなよっ", 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_007_002", 1, 9, 4, "油断大敵です", 5, 1000, "vo_minigame_1013_icon_2_007_002", "冷やっとしたぜ…！", 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_007_003", 1, 10, 4, "忌々しいっ…", 5, 1000, "vo_minigame_1013_icon_2_007_003", "弱音を吐くなっ", 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_008_001", 99, 11, 3, "大所帯ですわね", 6, 1500, "vo_minigame_1013_icon_2_008_001", "マコト班集合！", 4);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_008_002", 99, 12, 3, "エリコ班へようこそ", 6, 1500, "vo_minigame_1013_icon_2_008_002", "連携してくぞ！", 4);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_020_001", 0, 13, 6, "ナナカちゃんに\nお任せあれ", 8, 3000, "vo_minigame_1013_icon_2_020_001", "みんなに力を！", 1);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_022_001", 0, 14, 7, "はっはっは！\n任せろ！", 9, 3000, "vo_minigame_1013_icon_2_022_001", "任せてくれたまえ", 1);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_1_023_001", 0, 15, 8, "どんどんいくわよ", 10, 3000, "vo_minigame_1013_icon_2_023_001", "ほな、いきまひょか", 1);
